import {ledger,products,money,date,short} from './store.js';
import {esc,segmented,tooltip,dialog,toast,icon} from './ui.js';
import {visual,animateVisuals,marketImage,askerAvatar,productMark} from './visuals.js';
import {sentence} from './sentences.js';
import {outcomes,quote,csv,addresses,explorer} from './detail-logic.js';
import {communityPage,bindCommunity,recordFollow} from './community.js';

import {loadTrades,tradesFor,tape,recordsForAddress} from './trades.js';
import {tradeUrl,handoffAttrs,isNative} from './route-v2.js';

// Agent B integration: importing details installs inner styles and exposes optional shell hooks.
if(document.querySelector&&!document.querySelector('link[data-seer-inner]')){const link=document.createElement('link');link.rel='stylesheet';link.href=new URL('../inner.css',import.meta.url);link.dataset.seerInner='';document.head.append(link)}
const topLink=(url,text,cls='')=>`<a class="${cls}" href="${esc(url)}" target="_top">${esc(text)} ${icon('arrow')}</a>`;
const mlink=m=>'#/m/'+encodeURIComponent(m.id),alink=m=>'#/a/'+encodeURIComponent(m.asker.id);
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const followed=m=>read('seer.following',[]).includes(m.id);
const num=v=>v==null?'Not supplied':Number(v).toLocaleString('en',{maximumFractionDigits:6});
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const refresh=()=>window.dispatchEvent(new HashChangeEvent('hashchange'));
let current=null,tab='overview',range='all',amount=50,side='buy',out=0,context=null,ribbonTimeline=null,routeVersion=0,activePath='',boundRoot=null,wizardLineWidth=0;
const marketTabs=[['overview','Overview'],['trades','Trades & positions'],['activity','Activity'],['holders','Holders'],['resolution','Resolution'],['contracts','Contract & data'],['related','Related'],['comments','Comments']];
const priced=m=>({conditional:'Governance-token value if the proposal passes or fails.',scalar:`Expected value between ${Number(m.pricing.lowerBound)/1e18} and ${Number(m.pricing.upperBound)/1e18}.`,risk:'Annual default probability. Historical token quotes use different units.',field:m.product==='deep'?'UP prices original work; DOWN prices dependency contribution.':'Each entry’s forecast chance of selection. The sponsor decides.',binary:'The forecast probability of a Yes answer.',categorical:'The forecast probability of each possible answer.'}[m.pricing.kind]||'Recorded outcome quotes.');
const changes=m=>({futarchy:'Proposal details, token-value evidence, or the pass and fail prices.',deep:'Repository evidence, dependency attribution, or traders’ weights.',opportunity:'New submissions, reviewer evidence, or a sponsor decision.',risk:'Collateral, reserves, security, or the forecast horizon.',seer:'New evidence, changes to the resolution source, or new trades.'}[m.product]);
const avatar=askerAvatar;
function stats(items){const units=new Map();for(const m of items)if(m.volume!=null)units.set(m.amountUnit||'Unspecified units',(units.get(m.amountUnit||'Unspecified units')||0)+m.volume);return `<div class="entity-stats"><div><strong data-inner-count="${items.length}">${items.length}</strong><span>Questions</span></div><div><strong>${items.filter(m=>m.state==='Trading').length}</strong><span>Trading</span></div><div><strong>${items.filter(m=>m.state==='Resolved').length}</strong><span>Answered</span></div><div class="volume-stat"><strong>${units.size?[...units].map(([u,n])=>esc(money(n,u))).join('<br>'):'Not supplied'}</strong><span>Recorded volume · source units</span></div><div><strong>${new Set(items.map(m=>m.product)).size}</strong><span>Products</span></div></div>`}
export function detailPage(path,params,{row,depth='simple',lens='answer'}){
 activePath=path;
 if(path.startsWith('/t/')){current=null;return traderPage(path.slice(3))}
 const community=communityPage(path,{row,depth,lens});
 if(community!==null){current=null;return community}
 if(path.startsWith('/m/')){let id;try{id=decodeURIComponent(path.slice(3))}catch{return missing('Question')}
 const m=ledger.find(x=>x.id===id);if(!m){current=null;return missing('Question')}
 const requested=params.get('tab');if(current?.id!==m.id){range='all';out=0;amount=50;side='buy'}tab=marketTabs.some(([k])=>k===requested)?requested:'overview';const selected=params.get('outcome');if(selected!==null){const rows=outcomes(m),i=rows.findIndex(o=>String(o.i)===selected||o.name.trim().toLowerCase()===selected.trim().toLowerCase());if(i>=0)out=i}current=m;return marketPage(m,depth,lens)}
 current=null;
 if(path.startsWith('/a/')){let id;try{id=decodeURIComponent(path.slice(3))}catch{return missing('Asker')}const items=ledger.filter(m=>m.asker.id===id);if(!items.length)return missing('Asker');return askerPage(items,params,row)}
 if(path.startsWith('/p/')){const id=path.slice(3);return products[id]?productPage(id,row):missing('Product')}
 return null;
}
function missing(kind){return `<section class="secondary inner-page"><h1>${kind} not found.</h1><p>Browse the captured questions to find another signal.</p><a class="primary" href="#/">Return to Explore ${icon('arrow')}</a></section>`}
function askerPage(items,params,row){const m=items[0],a=m.asker,t=['questions','decisions','about'].includes(params.get('tab'))?params.get('tab'):'questions';return `<section class="secondary entity-page inner-page"><a class="back-link" href="#/askers">${icon('arrow')} All askers</a><header class="entity-heading">${avatar(a)}<div><h1>${esc(short(a.name))}</h1><p>${esc(a.kind)}${a.derived?' · source-derived role':''}</p></div></header>${a.address?`<div class="address-line"><code>${esc(a.address)}</code><button data-copy="${esc(a.address)}" aria-label="Copy asker address">${icon('grid')} Copy</button>${topLink(explorer(m)+'/address/'+a.address,'Explorer')}</div>`:'<p class="identity-note">The source names this role without a verified address.</p>'}${stats(items)}<div class="entity-tabs">${segmented([['questions','Questions'],['decisions','Decisions informed'],['about','About']],t,'asker-tab','tabs')}</div><div class="entity-panel" data-inner-reveal>${t==='questions'?items.map(row).join(''):t==='decisions'?items.map(x=>`<article class="decision-row">${marketImage(x)}<a href="${mlink(x)}"><h2>${esc(x.title)}</h2></a><p>${esc(sentence(x).answer)}</p><span class="action-chip">${esc(sentence(x).action)}</span></article>`).join(''):`<div class="reading-column"><h2>Questions with a purpose.</h2><p>${esc(a.name)} appears on ${items.length} captured questions across ${[...new Set(items.map(x=>products[x.product].name))].join(', ')}.</p><p>${a.derived?'Attribution is derived from product context; the source does not verify a legal identity.':'The source records this name and address.'}</p><h3>Decisions these signals inform</h3>${[...new Set(items.map(x=>x.useIt.decision))].map(d=>`<p>${esc(d)}</p>`).join('')}<a href="#/ask">Ask your own question ${icon('arrow')}</a></div>`}</div></section>`}
const hubCopy={seer:['Know what happens next.','One question. A forecast you can check.','Compare a probability with your evidence.'],deep:['See where original work lives.','Repository forecasts for research and funding.','UP and DOWN price contributions, not winner odds.'],futarchy:['A clearer view before the vote.','Compare a proposal’s two possible futures.','Conditional prices inform the vote. The DAO decides.'],opportunity:['Let the strongest work surface.','Market forecasts help focus a sponsor’s review.','Shortlist entries. The sponsor keeps the final say.'],risk:['Understand the exposure.','A common horizon for comparing asset risk.','Read annual default estimates alongside collateral evidence.']};
function productPage(id,row){const p=products[id],items=ledger.filter(m=>m.product===id),m=items.find(x=>x.pricing.headline.value!=null)||items[0],copy=hubCopy[id];return `<section class="secondary product-hub inner-page" data-product="${id}"><a class="back-link" href="#/">${icon('arrow')} Explore</a><header class="hub-heading"><div><span class="product-word">${productMark(id)}${p.name}</span><h1>${copy[0]}</h1><p>${copy[1]}</p></div>${topLink(p.url,'Open '+p.name,'primary')}</header><section class="hub-explainer" data-inner-reveal><div><h2>${esc(p.who)}</h2><p>${esc(m.useIt.decision)}</p><a href="${alink(m)}">Meet an asker ${icon('arrow')}</a></div><div class="hub-live">${marketImage(m,'shadow')}${visual(m)}<a href="${mlink(m)}">Read this signal ${icon('arrow')}</a></div><div><h2>${esc(sentence(m).action)}</h2><p>${copy[2]}</p><button data-explain="${esc(m.id)}">See how to read it ${icon('arrow')}</button></div></section>${stats(items)}<details class="hub-difference"><summary>How it differs from a prediction market</summary><p>${esc(p.description)} ${copy[2]}</p></details><div class="section-heading"><h2>${items.length} recorded questions</h2><a href="#/?product=${id}">Open in the index ${icon('arrow')}</a></div><div class="hub-records">${items.map(row).join('')}</div></section>`}
function marketPage(m,depth,lens){const s=sentence(m);return `<section class="detail market-page inner-page" data-depth="${depth}" data-lens="${lens}" data-product="${m.product}"><div class="detail-tools"><nav aria-label="Breadcrumb"><a href="#/">Explore</a><span> / </span><a href="#/p/${m.product}">${products[m.product].name}</a></nav><div class="detail-lenses">${segmented([['simple','Simple'],['pro','Pro']],depth,'depth')}${segmented([['answer','Answer'],['trade','Trade']],lens,'lens')}</div></div><header class="market-heading">${marketImage(m,'backdrop')}<a class="asker sentence-asker" href="${alink(m)}"><span style="view-transition-name:market-avatar">${avatar(m.asker)}</span><span><strong>${esc(short(m.asker.name))} asks</strong><small>${esc(m.asker.kind)}${m.asker.derived?' · role derived':''}</small></span></a><h1 style="view-transition-name:market-title">${esc(m.title.trim())}</h1><div class="market-meta-line"><span class="state">${esc(m.state)}</span><span>${esc(m.chain)}</span><button class="id-chip" data-copy="${esc(m.id)}" aria-label="Copy market ID">${esc(short(m.sourceId))} ${icon('grid')}</button><small>Snapshot · ${esc(m.compiledAt)}</small></div></header><div class="information-ribbon"><section class="ribbon-source"><span class="ribbon-caption">The question matters to</span><a href="${alink(m)}"><h2>${esc(short(m.asker.name))}</h2></a><p>${esc(m.useIt.decision)}</p><small>${m.closesTs?'Recorded close · '+date(m.closesTs):'Closing date not supplied'}</small></section><section class="ribbon-signal"><div style="view-transition-name:market-price">${visual(m)}</div><p class="spoken-answer">${esc(s.answer)}</p></section><section class="ribbon-action"><span class="ribbon-caption">Your next move</span><h2>${esc(s.action)}</h2><p>${esc(s.reason)}</p><button class="quiet-follow" data-follow="${esc(m.id)}" aria-pressed="${followed(m)}">${followed(m)?'Following':'Follow signal'} ${icon('arrow')}</button></section><svg class="ribbon-connector" viewBox="0 0 1000 24" preserveAspectRatio="none" aria-hidden="true"><path d="M0 12H645Q665 12 685 3H1000M645 12H1000M645 12Q665 12 685 21H1000"/></svg></div><div class="ribbon-controls"><button data-replay-ribbon>${icon('arrow')} Replay flow</button><button data-explain="${esc(m.id)}">Explain this signal ${icon('help')}</button></div><div class="market-body"><div class="market-main"><div class="market-tabs" role="tablist" aria-label="Market details">${marketTabs.map(([k,t])=>`<button role="tab" id="tab-${k}" aria-controls="market-panel" aria-selected="${tab===k}" tabindex="${tab===k?0:-1}" data-market-tab="${k}">${t}</button>`).join('')}<span class="tab-underline"></span></div><section id="market-panel" role="tabpanel" aria-labelledby="tab-${tab}" tabindex="0">${panel(m)}</section><details class="evidence-note"><summary>What would change this signal?</summary><p>${esc(changes(m))}</p><p>${m.liquidity==null?'Liquidity is not supplied in this snapshot.':'Recorded liquidity: '+esc(money(m.liquidity,m.amountUnit))+'.'} Compare the quote with your own evidence.</p></details><details class="for-asker"><summary>For the asker</summary><h2>Bring the evidence into your decision.</h2><p>${esc(m.useIt.sentence)}</p><div class="inline-actions"><button data-download="json">Download JSON ${icon('arrow')}</button><button data-download="csv">Export CSV ${icon('arrow')}</button><a href="#/ask?from=${encodeURIComponent(m.id)}">Ask something similar ${icon('arrow')}</a></div><h3>Read this record programmatically</h3><p>Static snapshot · example integration.</p><pre><code>${esc(subscription(m))}</code></pre><button data-copy="${esc(subscription(m))}">Copy request ${icon('grid')}</button></details></div><button class="primary mobile-ticket-trigger" data-mobile-ticket aria-expanded="false">${isNative(m)?'Preview quote · Trade in Seer':'Open '+products[m.product].name} ${icon('arrow')}</button><aside class="trade-ticket" data-lenis-prevent aria-label="Read-only quote and product hand-off"><button class="mobile-ticket-close" data-close-ticket>Close ${icon('close')}</button><div class="ticket-content">${ticket(m)}</div></aside></div></section>`}
function subscription(m){const endpoint=new URL('../data/ledger.json',import.meta.url).href;return `const markets = await fetch(${JSON.stringify(endpoint)}).then(r => r.json());\nconst signal = markets.find(m => m.id === ${JSON.stringify(m.id)});`}
function panel(m){
 if(tab==='trades')return marketTrades(m);
 if(tab==='overview')return `<div class="section-heading"><div><h2>How the quote moved</h2><p>${esc(priced(m))}</p></div>${segmented([['1d','1D'],['7d','7D'],['30d','30D'],['all','All']],range,'chart-range')}</div><div id="detail-chart">${priceChart(m)}</div><div class="section-heading outcome-heading"><h2>Possible answers</h2><span>${outcomes(m).length} outcomes</span></div><div class="data-scroll"><table class="detail-table"><thead><tr><th>Outcome</th><th>Recorded quote</th><th>Source unit</th></tr></thead><tbody>${outcomes(m).map(o=>`<tr class="selectable-outcome ${o.i===out?'is-selected':''}"><td><button class="outcome-select" data-select-outcome="${o.i}" aria-pressed="${o.i===out}"><span>${esc(o.name)}</span><small>${o.i===out?'Selected for preview':'Preview this outcome'}</small></button></td><td class="outcome-value">${num(o.p)}</td><td>${esc(m.pricing.quoteUnit||(['conditional','scalar'].includes(m.pricing.kind)?m.pricing.headline.unit:'fraction'))}${o.normalized?' · normalized':''}</td></tr>`).join('')}</tbody></table></div><details class="outcome-actions"><summary>Mint, merge & redeem</summary><p>Mint a complete set with collateral; merge that set to recover collateral. Redeem winning shares after final resolution.</p>${topLink(handoff(m),m.state==='Resolved'?'Check redemption in '+products[m.product].name:'Manage outcome shares in '+products[m.product].name)}</details>`;
 if(tab==='activity'){const events=[...(m.activity||[]),...(m.opensTs?[{timestamp:m.opensTs,type:'Trading opening recorded'}]:[]),...(m.closesTs?[{timestamp:m.closesTs,type:'Closing deadline recorded'}]:[]),...(m.oracle?.finalizeTs?[{timestamp:m.oracle.finalizeTs,type:'Answer finalization recorded'}]:[])].sort((a,b)=>(b.timestamp||b.ts)-(a.timestamp||a.ts));return `<h2>The recorded lifecycle</h2><p>Source events only. Price observations are not trades.</p><div class="activity-list">${events.length?events.map(e=>`<article><span class="event-dot"></span><div><h3>${esc(e.type||e.event||'Source event')}</h3><time>${date(e.timestamp||e.ts)}</time></div></article>`).join(''):'<div class="inner-empty"><h3>No event log was supplied.</h3><p>Inspect the full product for on-chain activity.</p></div>'}</div>${topLink(m.productUrl,'View activity in '+products[m.product].name)}`}
 if(tab==='holders')return marketTrades(m,'holder');
 if(tab==='resolution')return resolution(m);
 if(tab==='contracts')return `<h2>Trace the source.</h2><p>${esc(m.chain)} · chain ${m.chainId} · saved ${esc(m.compiledAt)}</p><div class="inline-actions"><button data-download="json">Market JSON ${icon('arrow')}</button><button data-download="csv">Outcomes CSV ${icon('arrow')}</button><button data-embed>Copy market link ${icon('grid')}</button></div>${m.product==='risk'?'<p>Asset slice of one shared contract, rather than a separate asset market.</p>':''}<dl class="record-fields">${addresses(m).map(x=>`<dt>${esc(x.label)}</dt><dd><code>${esc(x.address)}</code><div><button data-copy="${esc(x.address)}">Copy</button>${topLink(explorer(m)+'/address/'+x.address,'Explorer')}</div></dd>`).join('')}<dt>Oracle</dt><dd>${esc(m.oracle?.address||'Address not supplied')}</dd><dt>Router</dt><dd><code>${esc(m.metadata?.contractInfos?.futarchy?.router||m.router||'Address not supplied')}</code></dd></dl><details><summary>Source provenance</summary><pre>${esc(JSON.stringify(m.source,null,2))}</pre></details>`;
 if(tab==='comments')return comments(m);
 const parent=m.parentMarket?.id,items=ledger.filter(x=>x.id!==m.id&&(x.asker.id===m.asker.id||x.product===m.product||x.contract?.toLowerCase()===parent?.toLowerCase()||x.parentMarket?.id?.toLowerCase()===m.contract?.toLowerCase()));return `<h2>Follow the connections.</h2><p>Related questions from this asker, product, and conditional branches.</p><div class="related-list">${items.length?items.map(x=>`<a class="related-record" href="${mlink(x)}">${marketImage(x)}<span><small>${x.contract?.toLowerCase()===parent?.toLowerCase()?'Parent market':x.parentMarket?.id?.toLowerCase()===m.contract?.toLowerCase()?'Child market':x.asker.id===m.asker.id?'Same asker':products[x.product].name}</small><b>${esc(x.title)}</b></span>${icon('arrow')}</a>`).join(''):'<p>No related records were captured.</p>'}</div>`;
}
function resolution(m){const qs=m.resolution?.questions||[],arbitration=qs.some(q=>q.is_pending_arbitration),steps=['Question created','Trading & evidence','Awaiting an answer','Challenge window','Arbitration if requested','Final answer'],active=m.state==='Resolved'?5:arbitration?4:m.oracle?.finalizeTs?3:m.state==='Trading'?1:2;return `<h2>Evidence becomes an answer.</h2><p>Reality.eth records answers. Challenges may go to Kleros.</p><ol class="resolution-stepper">${steps.map((s,i)=>`<li class="${i===active?'current':''}" ${i===active?'aria-current="step"':''}><span class="step-dot"></span><div><b>${s}</b><small>${i===active?'Saved state':i===4?'Only when arbitration is requested':i<active?'Earlier stage; timestamp may be unavailable':'Next or conditional stage'}</small></div></li>`).join('')}</ol><dl class="record-fields"><dt>Oracle state</dt><dd>${esc(m.oracle?.status||'Not supplied')}</dd><dt>Answer bond ${tooltip('Collateral behind an answer; another participant can challenge it.')}</dt><dd>${esc(m.oracle?.bond??'Not supplied')} ${esc(m.oracle?.bond!=null?m.oracle.bondUnit||'raw units':'')}</dd><dt>Finalization</dt><dd>${date(m.oracle?.finalizeTs)}</dd><dt>Kleros</dt><dd>${qs.length?arbitration?'Arbitration pending':'No pending arbitration recorded':'State not supplied'}</dd><dt>Resolution rule</dt><dd>${esc(m.metadata?.description||m.title)}</dd><dt>Question ID</dt><dd><code>${esc(m.resolution?.questionId||'Not supplied')}</code></dd></dl><h3>Captured answer state</h3>${qs.length?qs.map(q=>`<details class="answer-record"><summary>${esc(short(q.id))}</summary><p>Best answer · <code>${esc(q.best_answer??'Not supplied')}</code></p><p>Challenge timeout · ${q.timeout??'Not supplied'} seconds</p><p>Finalization · ${date(q.finalize_ts)}</p>${q.arbitrator?topLink(explorer(m)+'/address/'+q.arbitrator,'Arbitrator contract'):''}</details>`).join(''):'<p>No answer history was supplied.</p>'}`}
function comments(m){const notes=read('seer.comments',{})[m.id]||[];return `<h2>Your notes on the signal.</h2><p>Private to this browser. No public comments were supplied.</p><form id="market-comment"><label for="comment-text">Add context for your next visit</label><textarea id="comment-text" name="comment" rows="3" minlength="2" maxlength="1200" required></textarea><button class="primary" type="submit">Save note ${icon('arrow')}</button></form><div class="comment-list">${notes.length?notes.map((n,i)=>`<article class="comment"><header><span>You · local note</span><small>${esc(new Date(n.time).toLocaleDateString('en'))}</small><button data-remove-note="${i}" aria-label="Delete note ${i+1}">${icon('close')}</button></header><p>${esc(n.text)}</p></article>`).join(''):'<p class="note-empty">No notes yet.</p>'}</div>`}
function handoff(m){return isNative(m)?tradeUrl(m):m.productUrl}
function ticket(m){const native=isNative(m);return `${marketImage(m,'shadow')}<div class="ticket-topline"><span>Read-only quote</span><span class="ticket-product">${avatar(m.asker)}${productMark(m.product)}${products[m.product].name}</span></div><h2>${esc(outcomes(m)[out]?.name||'Choose an outcome')}</h2><p>Saved snapshot. Trading happens in the product.</p><a class="primary ticket-handoff" href="${esc(handoff(m))}"${handoffAttrs()}${!native?' target="_top"':''}>${native?'Trade this market in Seer':'Trade in '+products[m.product].name} ↗</a><form id="quote-form"><label>Outcome<select name="outcome">${outcomes(m).map(o=>`<option value="${o.i}" ${o.i===out?'selected':''}>${esc(o.name)} · ${num(o.p)}</option>`).join('')}</select></label><label>Preview amount<input name="amount" inputmode="decimal" type="number" min="0.01" max="1000" step="any" value="${esc(amount)}" required></label><div class="quick-amounts">${[10,50,100,500].map(n=>`<button type="button" data-ticket-amount="${n}" aria-pressed="${Number(amount)===n}">${n}</button>`).join('')}</div><div class="quote-result" aria-live="polite">${quoteView(m)}</div></form><p class="ticket-disclosure">Demo preview; trading happens in the product. Fees and executable liquidity are not supplied.${native?' Select the outcome again in Seer.':' This product opens at the market; confirm the outcome there.'}</p><a class="ticket-help" href="#/how">How settlement works ${icon('arrow')}</a>`}
function quoteView(m){const q=quote(m,out,amount,side);if(q.error)return `<p class="quote-error" role="status">${esc(q.error)}</p>`;return `<dl><dt>Recorded token quote</dt><dd>${num(q.p)}</dd><dt>Quote unit</dt><dd>${esc(m.pricing.kind==='risk'?'Raw token price':m.pricing.quoteUnit||m.pricing.headline.unit||'Not supplied')}</dd><dt>Units per 100</dt><dd>${num(100/q.p)}</dd><dt>Preview units</dt><dd>${num(q.get)}</dd><dt>Maximum payout</dt><dd>${q.maxWin==null?'Product rules':num(q.maxWin)}</dd></dl><small>Arithmetic from the saved quote. No execution or price-impact estimate.</small>${m.pricing.kind==='risk'?'<small>Token quote differs from yearly default probability.</small>':''}`}
function observations(m){const all=(m.history||[]).filter(p=>p.values?.some(v=>Number.isFinite(v))),last=all.at(-1)?.ts;return range==='all'?all:all.filter(p=>p.ts>=last-({'1d':1,'7d':7,'30d':30}[range]||30)*86400)}
function chartScale(points){const vs=points.flatMap(p=>p.values.filter(Number.isFinite)),lo=Math.min(...vs),hi=Math.max(...vs),padding=(hi-lo||Math.max(Math.abs(hi)*.1,.01))*.12;return {low:lo-padding,high:hi+padding,x:i=>52+i/Math.max(1,points.length-1)*688,y:v=>218-(v-(lo-padding))/(hi-lo+2*padding)*184}}
export function priceChart(m){const pts=observations(m);if(!pts.length)return `<div class="inner-empty"><h3>No historical quotes in this range.</h3><p>Current recorded quotes remain below.</p></div>`;const {low,high,x,y}=chartScale(pts);const paths=m.pricing.outcomes.map((o,k)=>{let d='',previous=null;for(let i=0;i<pts.length;i++){const v=pts[i].values[k];if(!Number.isFinite(v)){previous=null;continue}const point={x:x(i),y:y(v)};if(!previous)d+=`M${point.x},${point.y}`;else{const mid=(previous.x+point.x)/2;d+=` C${mid},${previous.y} ${mid},${point.y} ${point.x},${point.y}`}previous=point}if(!d)return '';return `<path class="chart-line series-${k%3}" data-series="${k}" d="${d}"/>${pts.length===1?`<circle cx="${x(0)}" cy="${y(pts[0].values[k])}" r="4" class="single-point"/>`:''}`}).join('');return `<div class="interactive-chart" tabindex="0" role="img" aria-label="Saved quote chart, ${pts.length} observations. Use left and right arrows to inspect."><svg class="detail-price-chart" viewBox="0 0 780 260" preserveAspectRatio="none"><path class="chart-axis" d="M52 34H740M52 126H740M52 218H740"/><text x="0" y="30">${num(high)}</text><text x="0" y="238">${num(low)}</text>${paths}<path class="crosshair" d="M52 20V230"/><circle class="chart-point" cx="52" cy="${y(pts[0].values.find(Number.isFinite))}" r="4"/></svg><output class="chart-tooltip" hidden></output></div><div class="range-label"><span>${date(pts[0].ts)}</span><span>${date(pts.at(-1).ts)}</span></div><p class="chart-source">${esc(m.historyUnit||m.pricing.quoteUnit||'Raw outcome quotes')} · ${pts.every(p=>p.derived)?'Flat reconstruction; no historical movement asserted.':'Captured observations, not live.'}</p><details class="chart-observations"><summary>Inspect ${pts.length} observations</summary><div class="data-scroll"><table class="detail-table"><thead><tr><th>Timestamp</th>${m.pricing.outcomes.map(o=>`<th>${esc(o.name)}</th>`).join('')}</tr></thead><tbody>${pts.map(p=>`<tr><td>${new Date(p.ts*1000).toISOString()}</td>${m.pricing.outcomes.map((o,i)=>`<td>${num(p.values[i])}${p.derived?' · derived':''}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`}
function positionTabs(animate=true){const tabs=document.querySelector('.market-tabs'),selected=tabs?.querySelector('[aria-selected="true"]'),line=tabs?.querySelector('.tab-underline');if(!line||!selected)return;const vars={x:selected.offsetLeft,y:selected.offsetTop+selected.offsetHeight-2,width:selected.offsetWidth,duration:animate&&!reduced()?.4:0,ease:'power4.out'};if(window.gsap)gsap.to(line,vars);else{line.style.width=selected.offsetWidth+'px';line.style.transform=`translate(${selected.offsetLeft}px,${selected.offsetTop+selected.offsetHeight-2}px)`}}
