function playRibbon(){ribbonTimeline?.kill();const root=document.querySelector('.market-page');if(!root||reduced()||!window.gsap)return;const source=root.querySelector('.sentence-asker'),title=root.querySelector('.market-heading h1'),sections=root.querySelectorAll('.information-ribbon>section'),path=root.querySelector('.ribbon-connector path');ribbonTimeline=gsap.timeline({defaults:{ease:'power4.out',duration:.6}}).fromTo(source,{opacity:.35,y:8},{opacity:1,y:0},0).fromTo(title,{clipPath:'inset(0 0 100% 0)',y:12},{clipPath:'inset(0 0 0% 0)',y:0},.1).fromTo(sections[0],{opacity:.25,y:12},{opacity:1,y:0},.25).fromTo(path,{strokeDasharray:1700,strokeDashoffset:1700},{strokeDashoffset:0,duration:.85},.3).fromTo(sections[1],{opacity:.2,y:12},{opacity:1,y:0},.48).fromTo(sections[2],{opacity:.2,x:-12},{opacity:1,x:0},.78);drawCharts(root)}
function innerMotion(){context?.revert();context=null;ribbonTimeline?.kill();if(!window.gsap||reduced())return;const root=document.querySelector('.inner-page,.community');if(!root)return;context=gsap.context(()=>{root.querySelectorAll('[data-inner-reveal],.community-heading,.entity-heading,.hub-heading,.ask-layout,.developer-panel,.agent-roles,.worked-example,.entity-stats,.decision-row,.how-story-section').forEach((el,i)=>{gsap.from(el,{y:24,opacity:.25,filter:'blur(4px)',duration:.75,ease:'power4.out',scrollTrigger:window.ScrollTrigger?{trigger:el,start:'top 92%',once:true}:undefined,delay:window.ScrollTrigger?0:i*.04,clearProps:'transform,opacity,filter'})});root.querySelectorAll('[data-inner-count]').forEach(el=>{const counter={v:0};gsap.to(counter,{v:Number(el.dataset.innerCount),duration:.8,ease:'power3.out',scrollTrigger:window.ScrollTrigger?{trigger:el,start:'top 95%',once:true}:undefined,onUpdate:()=>el.textContent=Math.round(counter.v).toLocaleString('en')})});root.querySelectorAll('.process-line svg path,.how-story-section svg path').forEach(p=>{const length=p.getTotalLength();gsap.fromTo(p,{strokeDasharray:length,strokeDashoffset:length},{strokeDashoffset:0,ease:'none',scrollTrigger:window.ScrollTrigger?{trigger:p.closest('section'),start:'top 85%',end:'bottom 45%',scrub:.7}:undefined,duration:1})});},root);requestAnimationFrame(()=>window.ScrollTrigger?.refresh())}
export function bindDetails(){const mount=document.querySelector('#main')?.firstElementChild;if(mount&&mount===boundRoot)return;boundRoot=mount;routeVersion++;innerMotion();bindCommunity(refresh);enhanceInner(document.querySelector('.inner-page'));if(activePath.startsWith('/t/'))ensureEvidence();if(!document.querySelector('.market-page'))current=null;if(!current)return;ensureEvidence();enhanceInner(document.querySelector('.inner-page'));wireChart();positionTabs(false);playRibbon();requestAnimationFrame(()=>positionTabs(false))}
function wireChart(){const chart=document.querySelector('.interactive-chart');if(!chart||!current)return;const market=current,points=observations(market);if(!points.length)return;let index=0;const {x,y}=chartScale(points);function show(i){index=Math.max(0,Math.min(points.length-1,i));const p=points[index],cx=x(index);chart.querySelector('.crosshair').setAttribute('d',`M${cx} 20V230`);const dot=chart.querySelector('.chart-point');dot.setAttribute('cx',cx);dot.setAttribute('cy',y(p.values.find(Number.isFinite)));const output=chart.querySelector('output');output.hidden=false;output.innerHTML=`<strong>${esc(new Date(p.ts*1000).toLocaleString('en'))}</strong>${market.pricing.outcomes.slice(0,5).map((o,k)=>`<span>${esc(o.name)} <b>${num(p.values[k])}</b></span>`).join('')}${p.derived?'<small>Derived reconstruction</small>':''}`;output.style.left=Math.min(60,Math.max(2,cx/780*100))+'%'}chart.onpointermove=e=>show(Math.round(((e.clientX-chart.getBoundingClientRect().left)/chart.clientWidth*780-52)/688*(points.length-1)));chart.onpointerleave=()=>chart.querySelector('output').hidden=true;chart.onfocus=()=>show(index);chart.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();show(e.key==='Home'?0:e.key==='End'?points.length-1:index+(e.key==='ArrowRight'?1:-1))}}}
function updatePanel(){const y=scrollY;const target=document.querySelector('#market-panel');if(!target||!current)return;target.style.minHeight=Math.max(640,target.offsetHeight)+'px';target.innerHTML=panel(current);target.setAttribute('aria-labelledby','tab-'+tab);wireChart();drawCharts(target);requestAnimationFrame(()=>slideSegments(document,false));if(window.gsap&&!reduced())gsap.fromTo(target,{opacity:.35,y:8},{opacity:1,y:0,duration:.35,ease:'power3.out',clearProps:'transform,opacity'});enhanceInner(target);window.ScrollTrigger?.refresh();restoreScroll(y)}
function download(format){if(!current)return;const blob=new Blob([format==='csv'?csv(current):JSON.stringify(current,null,2)],{type:format==='csv'?'text/csv;charset=utf-8':'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=current.id+'.'+format;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(format.toUpperCase()+' downloaded')}
