function commandMatches(text,query){const clean=s=>s.toLowerCase().replace(/[^a-z0-9]/g,''),a=clean(text),b=clean(query);if(a.includes(b))return true;if(b.length<4)return false;let i=0;for(const c of a)if(c===b[i])i++;return i===b.length}
function commandResults(query=''){const target=document.querySelector('#inner-command-results');if(!target)return;const q=query.trim();let i=0;const group=(title,items)=>items.length?`<h3>${title}</h3>${items.map(([title,sub,url])=>`<a id="inner-result-${i++}" role="option" aria-selected="false" href="${esc(url)}"><span>${esc(title)}<small>${esc(sub)}</small></span>${icon('arrow')}</a>`).join('')}`:'';const people=[...new Map(ledger.map(m=>[m.asker.id,m.asker])).values()];target.innerHTML=q?group('Questions',ledger.filter(m=>commandMatches(m.title+' '+m.id+' '+m.contract,q)).slice(0,7).map(m=>[m.title,products[m.product].name+' · '+m.asker.name,mlink(m)]))+group('Outcomes',ledger.flatMap(m=>outcomes(m).filter(o=>commandMatches(o.name,q)).map(o=>[o.name,m.title,mlink(m)+'?outcome='+o.i])).slice(0,5))+group('Addresses', [...new Map(tape({q}).filter(r=>r.trader?.address).map(r=>[r.trader.address.toLowerCase(),r.trader])).values()].slice(0,4).map(t=>[t.name||short(t.address),'Saved records · identity unverified','#/t/'+encodeURIComponent(t.address)]))+group('Askers',people.filter(a=>commandMatches(a.name+' '+a.id+' '+(a.address||''),q)).slice(0,3).map(a=>[short(a.name),a.kind,'#/a/'+encodeURIComponent(a.id)]))+group('Products',Object.entries(products).filter(([,p])=>commandMatches(p.name,q)).map(([id,p])=>[p.name,p.description,'#/p/'+id]))+group('Pages',pageLinks.filter(x=>commandMatches(x[0]+' '+x[1],q))):group('Go to',pageLinks)+group('Products',Object.entries(products).map(([id,p])=>[p.name,ledger.filter(m=>m.product===id).length+' recorded questions','#/p/'+id]));if(!target.innerHTML)target.innerHTML=`<div class="command-empty"><p>No matching signals.</p><a href="#/?q=${encodeURIComponent(q)}">Search the full index ${icon('arrow')}</a></div>`;commandIndex=-1;document.querySelector('#inner-command-input')?.removeAttribute('aria-activedescendant')}
function selectCommand(index){const items=[...document.querySelectorAll('#inner-command-results [role=option]')];if(!items.length)return;commandIndex=(index+items.length)%items.length;items.forEach((a,i)=>a.setAttribute('aria-selected',String(i===commandIndex)));const selected=items[commandIndex];document.querySelector('#inner-command-input')?.setAttribute('aria-activedescendant',selected.id);selected.scrollIntoView({block:'nearest',behavior:'instant'})}
export function openCommand(){loadTrades().then(()=>{const field=document.querySelector('#inner-command-input');if(field)commandResults(field.value)}).catch(()=>{});const d=dialog('Find a signal',`<div class="command-search">${icon('search')}<input id="inner-command-input" type="search" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="true" aria-controls="inner-command-results" aria-label="Search questions, askers, products and pages" placeholder="Question, asker, address…"></div><div id="inner-command-results" role="listbox" aria-label="Search results"></div><div class="command-hint"><span>↑ ↓ to explore</span><span>Enter to open</span><span>Esc to close</span><span>${ledger.length} recorded questions</span></div>`);d.classList.add('command-dialog');const previousClose=d.onclose;d.onclose=()=>{d.classList.remove('command-dialog');previousClose?.()};commandResults();const input=d.querySelector('input');input.focus();input.oninput=()=>commandResults(input.value);input.onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();selectCommand(commandIndex<0?(e.key==='ArrowDown'?0:-1):commandIndex+(e.key==='ArrowDown'?1:-1))}if(e.key==='Enter'){e.preventDefault();const selected=d.querySelector('[aria-selected=true][role=option]')||d.querySelector('[role=option]');if(selected){selected.click();d.close()}else if(input.value.trim()){location.hash='/?q='+encodeURIComponent(input.value.trim());d.close()}}};d.onkeydown=e=>{if(!e.target.closest('#inner-command-results [role=option]')||!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();const items=[...d.querySelectorAll('[role=option]')],i=items.indexOf(document.activeElement);selectCommand(e.key==='Home'?0:e.key==='End'?items.length-1:i+(e.key==='ArrowDown'?1:-1));items[commandIndex]?.focus()};d.querySelector('#inner-command-results').onpointermove=e=>{const link=e.target.closest('[role=option]');if(link)selectCommand([...d.querySelectorAll('[role=option]')].indexOf(link))}}
export function explainMarket(id){const m=ledger.find(x=>x.id===id);if(!m)return;const s=sentence(m);dialog('Read this signal.',`<div class="explain-stations"><section class="explain-station"><small>${esc(m.asker.kind)}${m.asker.derived?' · source-derived role':''}</small><h3>${esc(m.asker.name)} asks</h3><p>${esc(m.title)}</p></section><section class="explain-station"><small>The recorded market view</small><h3>${esc(s.answer)}</h3><p>${esc(priced(m))}</p></section><section class="explain-station"><small>Your next move</small><h3>${esc(s.action)}</h3><p>${esc(s.reason)}</p></section></div><details><summary>What could move the answer?</summary><p>${esc(changes(m))}</p><p>Saved ${esc(m.compiledAt)}. A quote is evidence, never a guarantee.</p></details><div class="dialog-actions"><a class="primary" href="${mlink(m)}">Explore the question ${icon('arrow')}</a></div>`)}
export function openTour(step=0){tourStep=step;if(!tourMarket||!ledger.some(m=>m.id===tourMarket.id))tourMarket=current||ledger.find(m=>m.pricing.headline.value!=null&&m.product==='futarchy')||ledger[0];const m=tourMarket,s=sentence(m),steps=[['Someone needs an answer.',`${m.asker.name} asks`,m.title],['The market weighs in.',s.answer,priced(m)],['You make the decision.',s.action,s.reason],['Take the next step.',m.tradeable==='native'?'Preview a quote, then trade on Seer.':'Open this question in '+products[m.product].name+'.','This explorer uses saved data. Trading happens in the full product.']];const [title,statement,copy]=steps[step];const d=dialog(title,`<div class="tour-progress" aria-label="Step ${step+1} of 4">${steps.map((_,i)=>`<i class="${i<=step?'active':''}"></i>`).join('')}</div><h3>${esc(statement)}</h3><p>${esc(copy)}</p>${step===1?`<div class="tour-preview">${visual(m)}</div>`:''}<div class="dialog-actions"><button data-inner-tour-skip>Finish later</button>${step?'<button data-inner-tour-back>Back</button>':''}${step===3?`<a class="primary" href="${mlink(m)}">Explore this signal ${icon('arrow')}</a>`:'<button class="primary" data-inner-tour-next>Next '+icon('arrow')+'</button>'}</div>`);d.classList.add('inner-tour');const close=d.onclose;d.onclose=()=>{d.classList.remove('inner-tour');close?.()};if(step===1)drawCharts(d)}
