document.addEventListener('click',e=>{const control=e.target.closest('button,a');if(!control)return;const d=control.dataset;if('copy'in d){e.preventDefault();e.stopImmediatePropagation();copyText(d.copy,control)}else if('command'in d){e.preventDefault();e.stopImmediatePropagation();openCommand()}else if('explain'in d){e.preventDefault();e.stopImmediatePropagation();explainMarket(d.explain)}else if('help'in d){e.preventDefault();e.stopImmediatePropagation();tourMarket=current||null;openTour()}else if('innerClose'in d){e.preventDefault();e.stopImmediatePropagation();control.closest('dialog')?.close()}else if('innerTourNext'in d){e.preventDefault();e.stopImmediatePropagation();openTour(Math.min(3,tourStep+1))}else if('innerTourBack'in d){e.preventDefault();e.stopImmediatePropagation();openTour(Math.max(0,tourStep-1))}else if('innerTourSkip'in d){e.preventDefault();e.stopImmediatePropagation();try{localStorage.setItem('seer.tour','done')}catch{}control.closest('dialog')?.close()}else if(control.matches('#inner-command-results a,.inner-tour a,.explain-stations a')){control.closest('dialog')?.close()}if('follow'in d){const id=d.follow;setTimeout(()=>recordFollow(id),0)}},true);
document.addEventListener('keydown',e=>{if(!e.target.closest('input,textarea,select,[contenteditable]')&&window.gKey&&Date.now()-window.gKey<1500){const path={q:'/ask',t:'/traders',d:'/developers',f:'/watchlist'}[e.key];if(path){e.preventDefault();e.stopImmediatePropagation();window.gKey=0;location.hash=path;return}}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'||e.key==='/'&&!e.target.closest('input,textarea,select,[contenteditable]')){e.preventDefault();e.stopImmediatePropagation();openCommand()}},true);
function installDialogMotion(){const d=document.querySelector('#dialog');if(!d)return;let version=0;new MutationObserver(records=>{if(!records.some(r=>r.attributeName==='open'))return;if(!d.open)return;if(!d.querySelector('#inner-command-input'))d.classList.remove('command-dialog');version++;const n=version;if(window.gsap&&!reduced()){gsap.killTweensOf(d);gsap.fromTo(d,{opacity:.2,y:12,scale:.97,filter:'blur(6px)'},{opacity:1,y:0,scale:1,filter:'blur(0px)',duration:.32,ease:'power4.out',clearProps:'transform,filter,opacity'});const children=d.querySelectorAll('.explain-station,.dialog-actions>*,#inner-command-results a');if(children.length)gsap.fromTo(children,{opacity:.35,y:6},{opacity:1,y:0,stagger:.024,duration:.3,clearProps:'transform,opacity'})}requestAnimationFrame(()=>{if(n===version&&d.open&&!d.contains(document.activeElement))d.querySelector('input,button,a,textarea')?.focus()})}).observe(d,{attributes:true,attributeFilter:['open']});d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()})}
function slideSegments(root=document,animate=true){const progress=root.querySelector('.ask-progress'),step=progress?.querySelector('[aria-current=step]');if(progress&&step&&!progress.querySelector('.ask-progress-line')){const line=document.createElement('span');line.className='ask-progress-line';line.setAttribute('aria-hidden','true');progress.append(line);const next=step.offsetLeft+step.offsetWidth;if(window.gsap&&!reduced())gsap.fromTo(line,{width:wizardLineWidth},{width:next,duration:.45,ease:'power4.out'});else line.style.width=next+'px';wizardLineWidth=next}if(!progress)wizardLineWidth=0;root.querySelectorAll('.inner-page .segmented').forEach(group=>{const selected=group.querySelector('[aria-pressed=true]');if(!selected)return;let slider=group.querySelector('.inner-slider');if(!slider){slider=document.createElement('span');slider.className='inner-slider';slider.setAttribute('aria-hidden','true');group.prepend(slider)}const vars={x:selected.offsetLeft,width:selected.offsetWidth,duration:animate&&!reduced()?.35:0,ease:'power4.out'};if(window.gsap)gsap.to(slider,vars);else{slider.style.width=selected.offsetWidth+'px';slider.style.transform=`translateX(${selected.offsetLeft}px)`}})}
const baseBind=bindDetails;
if(typeof window!=='undefined')window.SeerInner={page:detailPage,bind:baseBind,communityPage,bindCommunity,command:openCommand,tour:openTour,explain:explainMarket,copy:copyText,refresh};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',installDialogMotion,{once:true});else if(document.querySelector)installDialogMotion();
document.addEventListener('click',e=>{if(e.target.closest('.inner-page .segmented')||e.target.closest('button')?.dataset?.boardPeriod!==undefined)requestAnimationFrame(()=>slideSegments(document,true))});
globalThis.addEventListener?.('resize',()=>slideSegments(document,false),{passive:true});
if(typeof MutationObserver!=='undefined')new MutationObserver(()=>requestAnimationFrame(()=>slideSegments(document,false))).observe(document.querySelector('#main')||document.body,{childList:true,subtree:false});

if(document.fonts?.ready)document.fonts.ready.then(()=>{positionTabs(false);slideSegments(document,false)});

// Agent B: saved evidence, explicit outcome selection and local tab updates.
let evidenceReady=false,evidenceError='',evidenceLoading=false,evidenceLimit=40;
const kindLabel=r=>r.side==='transfer'?'Token transfer':r.kind==='holder'?'Holder balance':r.side==='pool-snapshot'?'Pool snapshot':r.side==='pool-registry'?'Pool registry':r.kind==='liquidity'?'Pool observation':r.side||r.kind;
function replaceQuery(key,value){const [path,q='']=location.hash.split('?'),params=new URLSearchParams(q);params.set(key,value);history.replaceState(null,'',path+'?'+params)}
function restoreScroll(y){window.scrollTo({top:y,behavior:'instant'});(window.seerLenis||window.lenis)?.scrollTo?.(y,{immediate:true,force:true});requestAnimationFrame(()=>{if(Math.abs(scrollY-y)>1)window.scrollTo({top:y,behavior:'instant'})})}
function selectOutcome(index){if(!current||!outcomes(current)[index])return;const y=scrollY;out=index;side='buy';const host=document.querySelector('.ticket-content');if(host)host.innerHTML=ticket(current);document.querySelectorAll('[data-select-outcome]').forEach(b=>{const selected=Number(b.dataset.selectOutcome)===out;b.setAttribute('aria-pressed',String(selected));b.closest('tr')?.classList.toggle('is-selected',selected);const small=b.querySelector('small');if(small)small.textContent=selected?'Selected for preview':'Preview this outcome'});replaceQuery('outcome',String(out));if(tab==='trades')updatePanel();if(matchMedia('(max-width:800px)').matches)setTicket(true);restoreScroll(y)}
function ensureEvidence(){if(evidenceReady||evidenceLoading)return;evidenceLoading=true;loadTrades().then(()=>{evidenceReady=true;evidenceError=''}).catch(()=>{evidenceError='Saved records could not load.'}).finally(()=>{evidenceLoading=false;if(current&&['trades','holders'].includes(tab))updatePanel();const region=document.querySelector('#trader-evidence');if(region){const y=scrollY;region.innerHTML=traderEvidence(region.dataset.address);enhanceInner(region);restoreScroll(y)}})}
function evidenceRows(rows){return `<div class="inner-evidence-list">${rows.slice(0,evidenceLimit).map(r=>{const m=ledger.find(m=>m.id===r.marketId),address=r.trader?.address,href=m?mlink(m)+'?outcome='+encodeURIComponent(r.outcomeIndex??r.outcome??''):(r.productUrl||products[r.product]?.url),at=r.ts==null?null:new Date(typeof r.ts==='number'?r.ts*1000:r.ts);return `<article class="inner-evidence-row"><div class="evidence-market">${marketImage(m||{title:r.marketTitle||r.marketId,product:r.product})}<div><a href="${esc(href)}"${!m?' target="_top"':''}>${esc(m?.title||r.marketTitle||r.marketId)}</a><small>${productMark(r.product)}${esc(products[r.product]?.name||r.product)} · ${esc(r.outcome||'Outcome not supplied')}</small></div></div><div class="evidence-person">${address&&!/^0x0{40}$/i.test(address)?`<a href="#/t/${encodeURIComponent(address)}" title="${esc(address)}">${esc(r.trader.name||short(address))}</a>`:'<span>Identity not supplied</span>'}<span class="evidence-kind">${esc(kindLabel(r))}</span></div><dl><div><dt>Amount</dt><dd>${r.amount==null?'Not supplied':esc(r.amount)}<small>${esc(r.unit||'Unit not supplied')}</small></dd></div><div><dt>Quote</dt><dd>${r.price==null?'Not supplied':esc(r.price)}<small>${esc(r.priceUnit||'Source units')}</small></dd></div><div><dt>Observed</dt><dd>${at&&!Number.isNaN(at.getTime())?esc(at.toISOString().slice(0,16).replace('T',' ')+' UTC'):'Time not supplied'}<small>Saved sample</small></dd></div></dl><details class="evidence-source"><summary>Source evidence</summary><p>${esc(r.source?.note||'Captured observation; no execution inferred.')}</p><code>${esc(r.source?.file||'File not supplied')} ${esc(r.source?.pointer||'')}</code>${r.counterparty?`<p>Recipient · <a href="#/t/${encodeURIComponent(r.counterparty)}">${esc(short(r.counterparty))}</a></p>`:''}</details></article>`}).join('')}</div>${rows.length>evidenceLimit?`<button class="evidence-more" data-inner-evidence-more>Show ${Math.min(40,rows.length-evidenceLimit)} more records</button>`:''}`}
function evidenceState(){return evidenceError?`<div class="inner-empty" role="status"><h3>${esc(evidenceError)}</h3><button data-inner-evidence-retry>Retry saved records</button></div>`:'<div class="evidence-skeleton" role="status" aria-busy="true">Loading saved records…</div>'}
function marketTrades(m,kind){const rows=tradesFor(m.id).filter(r=>!kind||r.kind===kind);return `<div class="section-heading"><div><h2>${kind?'Recorded holders':'Trades & positions'}</h2><p>Saved samples. Transfers are not confirmed buys or sells.</p></div></div><div class="evidence-outcomes" aria-label="Select outcome for quote preview">${outcomes(m).map(o=>`<button data-select-outcome="${o.i}" aria-pressed="${o.i===out}">${esc(o.name)}</button>`).join('')}</div>${!evidenceReady?evidenceState():`<p class="evidence-count">${rows.length} records · ${rows.filter(r=>r.kind==='holder').length} holder balances · ${rows.filter(r=>r.side==='transfer').length} transfers</p>${rows.length?evidenceRows(rows):`<div class="inner-empty"><h3>No ${kind?'holder balances':'activity or positions'} supplied.</h3><p>Quotes and pool observations do not establish wallet holdings.</p>${topLink(handoff(m),'Inspect in '+products[m.product].name)}</div>`}`}`}
function traderPage(encoded){let address;try{address=decodeURIComponent(encoded)}catch{return missing('Address')}if(!/^0x[\da-f]{40}$/i.test(address))return missing('Address');return `<section class="secondary inner-page trader-page"><a class="back-link" href="#/traders">${icon('arrow')} All participants</a><header class="community-heading"><h1>${esc(short(address))}</h1><p>Records involving this address. Identity and wallet ownership are unverified.</p></header><div class="address-line"><code>${esc(address)}</code><button data-copy="${esc(address)}">Copy address</button></div><div id="trader-evidence" data-address="${esc(address)}">${traderEvidence(address)}</div></section>`}
function traderEvidence(address){if(!evidenceReady)return evidenceState();const rows=recordsForAddress(address),holders=rows.filter(r=>r.kind==='holder'),productsUsed=new Set(rows.map(r=>r.product));return `<div class="entity-stats"><div><strong>${rows.length}</strong><span>Saved records</span></div><div><strong>${holders.length}</strong><span>Holder observations</span></div><div><strong>${productsUsed.size}</strong><span>Products</span></div></div><p>Balances retain raw source units. Transfers can involve routers, pools or minting. No buy/sell direction or portfolio value is inferred.</p>${rows.length?evidenceRows(rows):'<div class="inner-empty"><h2>No saved records for this address.</h2><p>A leaderboard entry does not establish a market position.</p></div>'}`}
function switchAskerTab(value,button){const y=scrollY,root=button.closest('.entity-page'),panel=root?.querySelector('.entity-panel'),items=ledger.filter(m=>m.asker.id===decodeURIComponent(activePath.slice(3)));if(!panel||!items.length)return;const a=items[0].asker;let cache=root._askerPanels;if(!cache){cache=root._askerPanels={questions:panel.innerHTML};const currentTab=root.querySelector('[data-asker-tab][aria-pressed=true]')?.dataset.askerTab;if(currentTab&&currentTab!=='questions'){cache[currentTab]=panel.innerHTML;delete cache.questions}}if(!cache[value]){const output=askerPage(items,new URLSearchParams({tab:value}),m=>`<article class="decision-row">${marketImage(m)}<a href="${mlink(m)}"><h2>${esc(m.title)}</h2></a>${visual(m)}</article>`),template=document.createElement('template');template.innerHTML=output;cache[value]=template.content.querySelector('.entity-panel').innerHTML}panel.innerHTML=cache[value];root.querySelectorAll('[data-asker-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));replaceQuery('tab',value);enhanceInner(panel);slideSegments(root,true);if(window.gsap&&!reduced())gsap.fromTo(panel,{opacity:.4,y:6},{opacity:1,y:0,duration:.3,clearProps:'transform,opacity'});restoreScroll(y)}
function enhanceInner(root){if(!root)return;root.querySelectorAll('.market-row').forEach(row=>{const m=ledger.find(m=>m.id===row.dataset.market);if(!m)return;const a=row.querySelector('.avatar');if(a&&!a.classList.contains('inner-avatar'))a.outerHTML=askerAvatar(m.asker);const q=row.querySelector('.question');if(q&&!q.querySelector('.market-media')){q.querySelector('img')?.remove();q.insertAdjacentHTML('afterbegin',marketImage(m))}const tag=row.querySelector('.product-tag');if(tag&&!tag.querySelector('.inner-product-mark'))tag.insertAdjacentHTML('afterbegin',productMark(m.product))});root.querySelectorAll('img').forEach(img=>{img.loading='lazy';img.decoding='async'});animateVisuals(root)}
// Legacy shell hover previews are suppressed on B's inner records. Preview remains click-only.
document.addEventListener('pointerover',e=>{if(e.target.closest('.inner-page .market-row'))e.stopImmediatePropagation()},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-inner-evidence-more],[data-inner-evidence-retry]');if(b&&!current&&activePath.startsWith('/t/')){if('innerEvidenceRetry'in b.dataset){evidenceError='';ensureEvidence()}else{evidenceLimit+=40;const region=document.querySelector('#trader-evidence'),y=scrollY;if(region){region.innerHTML=traderEvidence(region.dataset.address);restoreScroll(y)}}}const preview=e.target.closest('.inner-page [data-peek]');if(preview){e.preventDefault();e.stopImmediatePropagation();const m=ledger.find(m=>m.id===preview.dataset.peek);if(!m)return;const s=sentence(m);dialog('Signal preview',`<div class="inner-peek">${marketImage(m,'backdrop')}<a class="asker" href="${alink(m)}">${askerAvatar(m.asker)}${esc(m.asker.name)}</a><h3>${esc(m.title)}</h3>${visual(m)}<p>${esc(s.answer)}</p><div class="dialog-actions"><a class="primary" href="${mlink(m)}">Open market ${icon('arrow')}</a>${topLink(handoff(m),'Trade in '+products[m.product].name)}</div></div>`)}},true);
